const items = [];
const cutoffMs = 2 * 60 * 60 * 1000; // 2 horas
const now = Date.now();

for (const item of $input.all()) {
  const xml = item.json.data || '';
  const entries = xml.match(/<item>[\s\S]*?<\/item>/g) || [];

  for (const entry of entries) {
    const title = (entry.match(/<title><!\[CDATA\[(.+?)\]\]><\/title>/) || [])[1] || '';
    const link = (entry.match(/<link>([^<]+)<\/link>/) || [])[1] || '';
    const description = (entry.match(/<description><!\[CDATA\[([\s\S]*?)\]\]><\/description>/) || [])[1] || '';
    const pubDate = (entry.match(/<pubDate>([^<]+)<\/pubDate>/) || [])[1] || '';
    const imageUrl = (entry.match(/<enclosure url="([^"]+)"/) || [])[1] || '';

    if (!link) continue;

    const pubTime = pubDate ? new Date(pubDate).getTime() : 0;
    if (now - pubTime > cutoffMs) continue; // mais de 2h, ignora

    items.push({
      json: {
        source: 'promobit',
        external_id: link,
        title: title.slice(0, 500),
        description: description.slice(0, 2000),
        url_original: link,
        store: 'promobit',
        image_url: imageUrl,
        price_current: 0, // Promobit não expõe preço no RSS
        raw_payload: { title, link, description, pubDate, imageUrl },
      }
    });
  }
}

return items;

const crypto = require('crypto');
const items = [];

for (const item of $input.all()) {
  const d = item.json;
  const hashInput = (d.url_original + (d.external_id || '')).toLowerCase().trim();
  const hashDedup = crypto.createHash('sha256').update(hashInput).digest('hex');

  items.push({
    json: {
      ...d,
      hash_dedup: hashDedup,
    }
  });
}

return items;
